// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address newOwner = address(0x1234);
        address nonAdmin = address(0xABCD);

        vm.prank(nonAdmin);
        c.setOwner(newOwner);

        // In reference, owner would be set to newOwner because onlyAdmin() has correct require (msg.sender == admin) which fails, so revert expected.
        // Actually re-analyzing: reference's onlyAdmin() requires msg.sender == admin, so nonAdmin call reverts => owner stays original msg.sender (deployer).
        // Buggy's onlyAdmin() always reverts, so also reverts. Wait - both revert? Let's check the difference statement: "after call completes, P.setOwner() != M.setOwner()" means one call succeeds.
        // Actually the statement says: P.setOwner() != M.setOwner() after the call. So one must succeed. The bug is require(false) always fails => revert always. Reference only fails for non-admin. So if we call as admin, reference succeeds, bug reverts.
        // Correct scenario: call as admin.

        // Reset with fresh contract
        c = new C();
        address admin = address(this); // deployer is admin

        vm.prank(admin);
        c.setOwner(newOwner);

        assertTrue(c.owner() == newOwner);
    }
}

