// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address admin = address(this);
        address nonAdmin = address(0x1234);

        // Step 1: As admin, set owner to a non-admin address
        c.setOwner(nonAdmin);

        // Step 2: Try from nonAdmin (new owner) to call setOwner again
        vm.prank(nonAdmin);
        // This call should revert in reference (only admin) but succeed in buggy (only owner)
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", admin));

        // Assert that the reference reverts (ok == false) while buggy would return true
        assertTrue(!ok, "Only admin should be able to call setOwner");
    }
}
